import React from 'react'
import {Wrapper, Background, InputContainer, ButtonContainer} from './styles';
import Card  from '../../components/Card';
import  background  from '../../assets/images/logo-preto.png';
import logoDynamous from '../../assets/images/logo-preto.png';
import Input from '../../components/Input';
import Button from '../../components/Button';
import { Link } from 'react-router-dom';

const SignIn = () => {
    return (
        <Wrapper>
            <Background image={background} />
            <Card width="403px">
            <img src={logoDynamous} width={172} height={61} alt="logo dynamous" />

            <InputContainer>
            <Input placeholder='EMAIL'/>
            <Input placeholder='SENHA' type="password"/>
            </InputContainer>

            <ButtonContainer>
                <Button type='button' >Entrar</Button>
                <p>Volte para pagina principal<Link to="/home"></Link></p>
            </ButtonContainer>

            </Card>
       </Wrapper>
    )
}

export default SignIn;
